(7402213, 1164550, 65234, '<td valign="top">Brings up all kinds of thoughts of the myriad little ways we spoil the beauty in the world, and at the same time, the capture is sublime.</td>', 'Brings up all kinds of thoughts of the myriad little ways we spoil the beauty in the world, and at the same time, the capture is sublime.', '2015-09-03 22:20:40.000000', NULL, 1),
(7402214, 1165045, 29011, '<td valign="top">It''s quite a neat scene with lots of potential. The tall blade of grass near the left sure does scream for attention. Nicely exposed but perhaps needs a few tweaks here and there. As usual easier said than done ;)</td>', 'It''s quite a neat scene with lots of potential. The tall blade of grass near the left sure does scream for attention. Nicely exposed but perhaps needs a few tweaks here and there. As usual easier said than done ;)', '2015-09-03 22:21:13.000000', NULL, 1),
